namespace XForge.DesignSystem.Core.Primitives;

/// <summary>
/// Represents the role of a participant in an AI conversation.
/// </summary>
public enum AiRole
{
    /// <summary>System message — sets behavior and context for the AI model.</summary>
    System,

    /// <summary>User message — input from the human participant.</summary>
    User,

    /// <summary>Assistant message — response generated by the AI model.</summary>
    Assistant,

    /// <summary>Tool message — result returned from a tool/function call.</summary>
    Tool,

    /// <summary>Other — fallback role for messages that don't fit standard categories.</summary>
    Other
}
